package com.perkvault.app;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.provider.Settings;import android.graphics.Color;import android.view.*;import android.widget.*;import org.json.*;import java.time.*;import java.util.*;import com.google.mlkit.vision.common.InputImage;import com.google.mlkit.vision.text.TextRecognition;import com.google.mlkit.vision.text.latin.TextRecognizerOptions;
public class MainActivity extends Activity {
 LinearLayout root,items; String filter="Active",query=""; ArrayDeque<Uri> scans=new ArrayDeque<>(); int ink=0xff18382b; int paper=0xfff5f4ec;
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(ink);getWindow().setNavigationBarColor(ink);home();Reminder.schedule(this);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},7);handle(getIntent());}
 void handle(Intent i){if(i.getBooleanExtra("quick",false))form("");else if(Intent.ACTION_SEND.equals(i.getAction())){Uri u=i.getParcelableExtra(Intent.EXTRA_STREAM);if(u!=null){scans.add(u);nextScan();}else form(i.getStringExtra(Intent.EXTRA_TEXT));}else if(Intent.ACTION_SEND_MULTIPLE.equals(i.getAction())){ArrayList<Uri> a=i.getParcelableArrayListExtra(Intent.EXTRA_STREAM);if(a!=null){scans.addAll(a);nextScan();}}}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(ink);t.setFontFeatureSettings("kern");if(size>=20)t.setTypeface(android.graphics.Typeface.create("sans-serif-medium",0));t.setPadding(0,dp(7),0,dp(7));return t;}
 Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setTextSize(14);b.setBackground(shape(0xff214b36,12));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(48));bp.setMargins(0,dp(5),0,dp(5));b.setLayoutParams(bp);b.setOnClickListener(v->r.run());return b;}
 android.graphics.drawable.GradientDrawable shape(int color,int radius){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 protected void onResume(){super.onResume();render();}
 int page=0; boolean dark; LinearLayout body,nav; int lime=0xffdfff65, forest=0xff143b2d; int surface(){return dark?0xff244438:0xffffffff;} int fg(){return dark?0xfff5f4ec:forest;}
 LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 TextView label(String s,int size,int color){TextView t=text(s,size);t.setTextColor(color);return t;}
 void home(){dark=getPreferences(0).getBoolean("dark",false);ink=fg();paper=dark?0xff102b22:0xfff5f4ec;LinearLayout shell=column();shell.setBackgroundColor(paper);shell.setFitsSystemWindows(true);LinearLayout head=column();head.setPadding(dp(20),dp(12),dp(20),dp(12));head.setBackgroundColor(forest);head.addView(label("%   PerkVault",25,Color.WHITE));shell.addView(head);ScrollView scroll=new ScrollView(this);root=column();root.setPadding(dp(16),dp(16),dp(16),dp(16));scroll.addView(root);shell.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));nav=new LinearLayout(this);nav.setBackgroundColor(surface());String[] names={"Home","My Vault","Add","Reminders","Profile"};for(int j=0;j<names.length;j++){final int n=j;TextView t=label(names[j],12,fg());t.setGravity(Gravity.CENTER);t.setPadding(0,dp(15),0,dp(15));if(page==j){t.setBackground(shape(lime,12));t.setTextColor(forest);}nav.addView(t,new LinearLayout.LayoutParams(0,-2,1));t.setOnClickListener(v->{page=n;home();});}shell.addView(nav);setContentView(shell);items=null;if(page==0){root.addView(text("Your rewards, organised.",26));root.addView(text("Never miss a saving",14));items=column();root.addView(items);render();}else if(page==1){root.addView(text("My Vault",26));EditText search=new EditText(this);search.setHint("Search coupons, vouchers...");search.setTextColor(fg());search.setHintTextColor(0xff819087);root.addView(search);search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){query=s.toString();render();}public void afterTextChanged(android.text.Editable e){}});Spinner sp=new Spinner(this);sp.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Active","All","Used","Expired","Gift card","Loyalty"}));root.addView(sp);items=column();root.addView(items);sp.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int n,long id){filter=p.getItemAtPosition(n).toString();render();}});render();}else if(page==2){root.addView(text("Add Coupon",28));root.addView(button("Scan / Screenshot",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,12);}));root.addView(button("Manual entry",()->form("")));root.addView(button("From apps • Quick Save",()->floating()));root.addView(text("Share screenshots directly to PerkVault from any supported app.",16));}else if(page==3){root.addView(text("Expiry reminders",28));Switch enabled=new Switch(this);enabled.setText("Enable reminders");enabled.setTextColor(fg());enabled.setChecked(getSharedPreferences("prefs",0).getBoolean("remind",true));root.addView(enabled);enabled.setOnCheckedChangeListener((v,on)->getSharedPreferences("prefs",0).edit().putBoolean("remind",on).apply());for(int day:new int[]{7,3,1,0}){CheckBox c=new CheckBox(this);c.setText(day==0?"On expiry date":day+" days before");c.setTextColor(fg());c.setChecked(getSharedPreferences("prefs",0).getBoolean("day"+day,true));root.addView(c);c.setOnCheckedChangeListener((v,on)->getSharedPreferences("prefs",0).edit().putBoolean("day"+day,on).apply());}root.addView(text("Reminders are approximate and depend on Android battery settings.",14));}else{root.addView(text("Settings",28));root.addView(button("Floating Quick Save",()->floating()));root.addView(button("Stop floating button",()->stopService(new Intent(this,Bubble.class))));root.addView(button("Quick Settings tile",()->new AlertDialog.Builder(this).setTitle("Quick Settings").setMessage("Swipe down twice, edit tiles and add Save voucher.").setPositiveButton("OK",null).show()));root.addView(button("Notification Quick Save",()->shortcut()));root.addView(button(dark?"Switch to light mode":"Switch to dark mode",()->{getPreferences(0).edit().putBoolean("dark",!dark).apply();home();}));root.addView(text("Local wallet • No notification tracking",14));}}
 void floating(){if(!Settings.canDrawOverlays(this)){startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));return;}startForegroundService(new Intent(this,Bubble.class));}
 void shortcut(){NotificationManager n=getSystemService(NotificationManager.class);n.createNotificationChannel(new NotificationChannel("quick","Quick Save",NotificationManager.IMPORTANCE_LOW));if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0){requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},7);return;}n.notify(9,new Notification.Builder(this,"quick").setSmallIcon(android.R.drawable.ic_menu_save).setContentTitle("Quick Save Coupon").setContentText("Tap to paste a voucher code").setContentIntent(PendingIntent.getActivity(this,9,new Intent(this,MainActivity.class).putExtra("quick",true),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT)).setOngoing(true).build());}
 void render(){if(items==null)return;items.removeAllViews();JSONArray a=Store.read(this);double saved=0;int active=0,usedCount=0,soon=0;for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o.optBoolean("used")){usedCount++;saved+=o.optDouble("saved",0);}else if(!Store.expired(o)){active++;if(days(o)<=7)soon++;}}if(page==0){TextView summary=label("Actual savings\n₹"+String.format(Locale.US,"%.2f",saved),30,forest);summary.setBackground(new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TL_BR,new int[]{lime,0xffffb65b}));summary.setPadding(dp(18),dp(22),dp(18),dp(22));items.addView(summary);items.addView(text(active+" Active     "+soon+" Expiring     "+usedCount+" Used",17));items.addView(button("+ Add coupon",()->{page=2;home();}));items.addView(text("Expiring soon",22));}int shown=0;for(int i=0;i<a.length();i++){final int index=i;JSONObject o=a.optJSONObject(i);boolean used=o.optBoolean("used"),exp=Store.expired(o);if(page==0?(used||exp||days(o)>7):(filter.equals("Active")&&(used||exp)||filter.equals("Used")&&!used||filter.equals("Expired")&&!exp||filter.equals("Gift card")&&!o.optString("type").equals(filter)||filter.equals("Loyalty")&&!o.optString("type").equals(filter)||!o.toString().toLowerCase().contains(query.toLowerCase())))continue;shown++;LinearLayout card=column();card.setPadding(dp(16),dp(12),dp(16),dp(12));card.setBackground(shape(surface(),18));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,dp(5),0,dp(5));items.addView(card,cp);card.addView(text(o.optString("brand")+"  ›",22));card.addView(text(o.optString("source")+"  •  "+o.optString("type"),13));card.addView(text(o.optString("details"),15));card.addView(label(used?"Used":exp?"Expired":o.optString("expiry","No expiry"),13,!used&&!exp&&days(o)<=7?0xffd45a36:fg()));card.setOnClickListener(v->detail(a,index,o));}if(shown==0)items.addView(text(page==0?"No vouchers expiring soon.":"No matching vouchers. Add your first reward.",16));}
 long days(JSONObject o){try{return java.time.temporal.ChronoUnit.DAYS.between(LocalDate.now(),LocalDate.parse(o.optString("expiry")));}catch(Exception e){return Long.MAX_VALUE;}}
 void detail(JSONArray a,int index,JSONObject o){LinearLayout l=column();l.setPadding(dp(20),dp(12),dp(20),dp(12));l.addView(text(o.optString("source"),14));l.addView(text(o.optString("details"),18));l.addView(text("Expiry: "+o.optString("expiry"),15));l.addView(text(o.optString("code"),24));AlertDialog d=new AlertDialog.Builder(this).setTitle(o.optString("brand")).setView(l).setNegativeButton("Close",null).create();l.addView(button("Copy code",()->{((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Voucher",o.optString("code")));Toast.makeText(this,"Copied",0).show();}));l.addView(button(o.optBoolean("used")?"Mark unused":"Mark used",()->{d.dismiss();EditText e=new EditText(this);e.setInputType(8194);e.setHint("Actual savings in ₹");new AlertDialog.Builder(this).setTitle("Record savings").setView(e).setPositiveButton("Save",(x,w)->{try{boolean used=!o.optBoolean("used");o.put("used",used);o.put("saved",used&&e.length()>0?Double.parseDouble(e.getText().toString()):0);Store.write(this,a);render();}catch(Exception ex){}}).show();}));l.addView(button("Delete voucher",()->new AlertDialog.Builder(this).setMessage("Delete this reward?").setPositiveButton("Delete",(x,w)->{a.remove(index);Store.write(this,a);d.dismiss();render();}).setNegativeButton("Cancel",null).show()));d.show();}
 void form(String raw){Capture.show(this,raw,()->{render();nextScan();});}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==12&&c==RESULT_OK&&d!=null){if(d.getClipData()!=null)for(int i=0;i<d.getClipData().getItemCount();i++)scans.add(d.getClipData().getItemAt(i).getUri());else if(d.getData()!=null)scans.add(d.getData());nextScan();}}
 void nextScan(){if(scans.isEmpty())return;Uri u=scans.remove();try{var recognizer=TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);recognizer.process(InputImage.fromFilePath(this,u)).addOnSuccessListener(t->{recognizer.close();form(t.getText());}).addOnFailureListener(e->{recognizer.close();Toast.makeText(this,"Scan failed",0).show();nextScan();});}catch(Exception e){nextScan();}}
}
